#!/usr/bin/env bash
# Print up to the three most frequent client IPs in access.log.  AWK keeps
# each address's encounter order so equal counts retain their first appearance.
awk '
{
    ip = $1
    if (!(ip in count)) {
        order[++unique] = ip
    }
    count[ip]++
}
END {
    limit = unique < 3 ? unique : 3
    for (rank = 1; rank <= limit; rank++) {
        best = ""
        for (i = 1; i <= unique; i++) {
            ip = order[i]
            if (!(ip in selected) && (best == "" || count[ip] > count[best])) {
                best = ip
            }
        }
        print best
        selected[best] = 1
    }
}
' access.log
